"use client";
import {ArtemisScope} from "./artemis-scope";
import View2 from "./components/not-found-pages/variants/03-elastic";
const views={"elastic":View2};
export interface ArtemisNotFoundPagesProps{className?:string;variant?:"elastic";}
export function ArtemisNotFoundPages({className,variant="elastic"}:ArtemisNotFoundPagesProps){const View=views[variant];return <ArtemisScope className={["art:min-h-dvh art:[&>section]:min-h-dvh",className].filter(Boolean).join(" ")}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
export default function NotFoundPagesElastic() {
    const reduce = useReducedMotion();
    const [shown, setShown] = useState(false);
    useEffect(() => {
        if (reduce) {
            setShown(true);
            return;
        }
        const timer = setTimeout(() => setShown(true), 70);
        return () => clearTimeout(timer);
    }, [reduce]);
    const digit = (index: number) => ({
        initial: { opacity: 0, y: "24%", scaleY: 0.82 },
        animate: shown ? { opacity: 1, y: 0, scaleY: 1 } : undefined,
        whileHover: reduce ? undefined : index === 1 ? { y: -12, scaleY: 1.12 } : { y: 14, scaleY: 0.82 },
        transition: reduce ? { duration: 0 } : { ...ARTEMIS_SPRING_PANEL, delay: index * 0.055 },
    });
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    return (<>
      <section className="art:flex art:min-h-[680px] art:w-full art:flex-col art:overflow-hidden art:bg-primary art:text-primary-foreground art:[container-type:inline-size]">
        <header className="art:flex art:min-h-20 art:items-center art:justify-between art:px-5 art:@min-[640px]/artemis:px-8">
          <a href="/" className="art:font-medium art:text-sm art:focus-visible:outline-2 art:focus-visible:outline-ring">
            {"Index"}
          </a>
          <span className="art:font-mono art:text-xs art:uppercase art:tracking-[0.18em] art:opacity-55">
            {"404"}
          </span>
        </header>
        <div className="art:flex art:flex-1 art:flex-col art:items-center art:justify-center art:px-5 art:py-10 art:text-center">
          <div className="art:group art:flex art:items-end art:justify-center art:overflow-hidden art:py-[7cqw]">
            <motion.span {...digit(0)} className="art:block art:origin-bottom art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.12em]">
              {"4"}
            </motion.span>
            <motion.span {...digit(1)} className="art:block art:origin-bottom art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.12em]">
              {"0"}
            </motion.span>
            <motion.span {...digit(2)} className="art:block art:origin-bottom art:font-semibold art:text-9xl art:leading-tight art:tracking-[-0.12em]">
              {"4"}
            </motion.span>
          </div>
          <motion.h1 initial={{ opacity: 0 }} animate={shown ? { opacity: 1 } : undefined} transition={reduce ? { duration: 0 } : { duration: 0.2, ease: "easeOut", delay: 0.16 }} className="art:tracking-[-0.03em] art:text-4xl art:@min-[768px]/artemis:text-5xl art:font-medium">
            {"Out of bounds."}
          </motion.h1>
          <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-5 art:bg-primary-foreground art:text-primary art:hover:bg-primary-foreground/85 art:h-9 art:rounded-full" href="/" tabIndex={0}>
            {"Back to index"}
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
              <path d="M7 7h10v10"/>
              <path d="M7 17 17 7"/>
            </svg>
          </motion.a>
        </div>
      </section>
    </>);
}
